(()=>{
'use strict';
const $=s=>document.querySelector(s),main=$('#main'),overlay=$('#overlay'),KEY='sangarsazan.save.v1';
let engine=null,chapter=CHAPTERS[0],screen='home',order=[],hintCount=0,sound=false,audio=null,timer=null,saveOk=true,pendingImport=null;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const digits=x=>String(x).replace(/\d/g,d=>'۰۱۲۳۴۵۶۷۸۹'[d]);
function saveKey(id=chapter.id){return KEY+'.'+id}
function readSave(id=chapter.id){try{return localStorage.getItem(saveKey(id))||(id===CHAPTERS[0].id?localStorage.getItem(KEY):null)}catch{return null}}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(timer);timer=setTimeout(()=>$('#toast').style.display='none',3500)}
function save(){if(!engine)return;try{localStorage.setItem(saveKey(chapter.id),engine.export());saveOk=true}catch{saveOk=false;toast('ذخیره خودکار در این مرورگر ممکن نیست. از فهرست، خروجی ذخیره بگیر.')}}
function scene(id){$('#landscape').innerHTML=GameArt.scenes[id]||GameArt.scenes.marsh}
function modal(title,html,wide=false){overlay.classList.toggle('art-modal',wide);$('#modalTitle').textContent=title;$('#modalBody').innerHTML=html;if(!overlay.open)overlay.showModal()}
function close(){overlay.close()}
function home(){screen='home';document.body.classList.add('hub-screen');scene('core');main.innerHTML='<section class="home hub-page"><div class="home-copy"><div class="eyebrow">سنگرسازان · هسته بازی</div><h1>روایت‌هایی از<br><em>جهادگران</em></h1><p class="intro">تو در نقش محمد، جهادگر جوان این روایت، وارد دنیایی از مأموریت‌های مستقل می‌شوی. هر عملیات داستان، شخصیت‌ها و انتخاب‌های خودش را دارد.</p><button class="primary" data-action="operations">انتخاب عملیات ←</button><div class="chapter-tag">یک هسته بازی، چند عملیات مستقل</div></div><div class="core-caption"><span>محمد</span><small>جهادگر جوان و شخصیت خیالی بازی</small></div></section>'}
function operations(){screen='operations';document.body.classList.add('hub-screen');scene('marsh');const id=CHAPTERS[0].id;main.innerHTML='<section class="operations-page hub-page"><div class="hub-heading"><div><div class="eyebrow">فهرست مأموریت‌ها</div><h1>کدام عملیات؟</h1></div><button class="quiet" data-action="home">← بازگشت به هسته</button></div><div class="operation-grid"><article class="operation-card"><button class="operation-cover" data-chapter="'+id+'" aria-label="ورود به عملیات خیبر"><img src="'+GameArt.assets.hoorDay+'" alt="نمای روز هور با انعکاس نور روی آب"><span class="cover-label">عملیات خیبر</span></button><div class="operation-info"><div class="panel-kicker">عملیات · خیبر</div><h2>راهی میان آب</h2><p>در نقش محمد، به گروه مهندسی جهاد سازندگی بپیوند و سرنخ‌های مسیر را دنبال کن.</p><div class="operation-meta">تصویرسازی واقع‌گرایانه از هور · مأموریت روایی نمونه</div><button class="primary" data-chapter="'+id+'">'+(readSave(id)?'ادامه عملیات ←':'ورود به عملیات ←')+'</button></div></article></div></section>'}function newGame(){document.body.classList.remove('hub-screen');engine=new StoryEngine.Engine(chapter);order=[];hintCount=0;screen='game';save();render()}function restart(){if(!engine){newGame();return}modal('شروع بازی از ابتدا','<p>شروع تازه از معرفی محمد آغاز می‌شود و پیشرفت فعلی این عملیات را جایگزین می‌کند.</p><div class="panel-actions"><button class="primary" data-action="confirmRestart">شروع از اول</button><button data-action="resume">ادامه بازی فعلی</button></div>')}
function requestNew(){if(readSave())modal('شروع دوباره',`<p>پیشرفت مأموریت فعلی جایگزین می‌شود. می‌توانی قبل از شروع، از فهرست خروجی ذخیره بگیری.</p><button class="primary" data-action="confirmNew">شروع مأموریت تازه</button><button data-action="close">بازگشت</button>`);else newGame()}
function continueGame(){document.body.classList.remove('hub-screen');try{engine=new StoryEngine.Engine(chapter,readSave());screen='game';order=[];render()}catch{modal('ذخیره خوانده نشد','<p>ذخیره این عملیات قابل استفاده نیست. می‌توانی فایل ذخیره دیگری وارد کنی یا مأموریت تازه‌ای شروع کنی.</p><button data-action="import">ورود ذخیره</button><button data-action="confirmNew">شروع تازه</button>')}}
function tools(){return `<div class="tools"><button data-action="journal">دفتر <span>${digits(engine.state.journal.length)}</span></button><button data-action="map">نقشه</button><button data-action="gallery">تصاویر</button><button data-action="hint">راهنما</button></div>`}
function comicView(n){const i=engine.comicPanel(),p=n.panels[i];return '<section class="comic-reader"><div class="comic-heading"><div><div class="panel-kicker">روایت تصویری</div><h2>'+esc(n.title)+'</h2></div><button data-action="comicPage">صفحه کامل ⤢</button></div><div class="comic-layout"><figure class="comic-spread"><img class="comic-page-image" src="'+GameArt.assets.comic+'" alt="صفحه کمیک شش‌قابی محمد و مهندس پورشریفی، از جلسه کارگاه تا ساحل هور"><div class="comic-mobile-frame">'+GameArt.frame(p.frame,'قاب '+digits(i+1))+'</div></figure><aside class="comic-reading" aria-live="polite"><div class="panel-kicker">قاب '+digits(i+1)+' از '+digits(n.panels.length)+'</div><div class="comic-progress" aria-label="پیشرفت صفحه">'+n.panels.map((_,j)=>'<span class="'+(j===i?'active':'')+'">'+digits(j+1)+'</span>').join('')+'</div><h3>'+esc(p.speaker)+'</h3><p>'+esc(p.text)+'</p><div class="comic-controls"><button class="primary" data-action="advanceComic">'+(i===n.panels.length-1?'بررسی مدارک ←':'قاب بعد ←')+'</button><button data-action="previousComic" '+(i===0?'disabled':'')+'>قاب قبل</button></div><p class="save-status">قاب فعلی هم همراه پیشرفت بازی ذخیره می‌شود.</p><p class="notice">دیالوگ‌ها بازآفرینی داستانی‌اند؛ چهره مهندس بر پایه عکس آرشیوی طراحی شده است.</p></aside></div></section>'}
function comicPage(){modal('صفحه کامل کمیک','<img class="gallery-image" src="'+GameArt.assets.comic+'" alt="صفحه کامل کمیک شش‌قابی"><p class="notice">برای خواندن متن، به نمایش قاب‌به‌قاب برگرد.</p>',true)}
function gallery(){modal('چهره‌ها و روایت تصویری','<p>محمد، جهادگر جوان خیالی، و مهندس پورشریفی با طراحی برگرفته از عکس آرشیوی. نشان جهاد سازندگی روی سینه هر دو قرار دارد.</p><img class="gallery-image" src="'+GameArt.assets.characters+'" alt="محمد در چپ و مهندس پورشریفی در راست، با نشان جهاد سازندگی روی سینه"><h3>قاب‌های تازه خیبر</h3>'+[1,2,3,4,5,6].map((i)=>'<img class="gallery-image" src="'+GameArt.assets['scene'+i]+'" alt="تصویر کمیک '+i+' از محمد و مهندس پورشریفی در عملیات خیبر">').join('')+'<h3>ساحل هور در شب</h3><img class="gallery-image gallery-night" src="'+GameArt.assets.night+'" alt="تصویر شبانه کارگاه و پل شناور، ارسالی متین"><button class="primary" data-action="comicPage">دیدن صفحه کامل کمیک</button>',true)}
function render(){document.body.classList.remove('hub-screen');const n=engine.current();screen='game';scene(n.scene);const top=`<div class="game-top"><div><div class="chapter-title">${chapter.subtitle} / ${chapter.title}</div><div class="objective">◇ ${esc(n.objective||'گفت‌وگو را دنبال کن')}</div></div>${tools()}</div>`;let content='';
if(n.type==='comic'){content=comicView(n)}
else if(n.type==='inspect'){content=`<section class="content-panel mission-desk"><div class="desk-kicker"><span class="desk-pin"></span><span class="panel-kicker">میز کارگاه · پروندهٔ خیبر</span><span class="desk-ref">برگه‌های مأموریت</span></div><h2>${n.title}</h2><p class="panel-copy">${n.text}</p><div class="evidence-grid">${n.items.map(i=>`<button class="evidence evidence-${i.id}" data-inspect="${i.id}"><span class="evidence-visual evidence-visual-${i.id}" ${'style="--evidence-image:url('+(i.id==='map'?GameArt.assets.operationMap:i.id==='report'?GameArt.assets.operationPhoto:GameArt.assets.operationIRNA)+')"'}><span class="visual-heading">${esc(i.title)}</span><span class="visual-detail">${i.id==='report'?'قطعات نشان آبی · گزارش ساحل':i.id==='label'?'آبی: آماده بازبینی · زرد: نیازمند بررسی':'کارگاه ← ساحل ← محل آزمایش'}</span><span class="visual-mark">${i.id==='report'?'≋':i.id==='label'?'▱':'⌁'}</span></span><span class="evidence-title">${esc(i.title)}</span><span class="read-label">${engine.state.flags[i.id]?'✓ خوانده شد':'برای بررسی باز کن'}</span></button>`).join('')}</div><div class="panel-actions"><span class="hint">${digits(n.required.filter(x=>engine.state.flags[x]).length)} از ${digits(n.required.length)} مدرک بررسی شده</span><button class="primary" data-action="finishInspect">برگشت به گفت‌وگو ←</button></div></section>`}
else if(n.type==='puzzle'){content=`<section class="content-panel"><div class="panel-kicker">میز کار گروه</div><h2>${n.title}</h2><p class="panel-copy">${n.text}</p><div class="slots">${[0,1,2,3].map((_,i)=>`<div class="slot ${order[i]?'filled':''}"><span>گام ${digits(i+1)}</span>${order[i]?n.items.find(x=>x.id===order[i]).label:'کارت را انتخاب کن'}</div>`).join('')}</div><div class="puzzle-bank">${n.items.map(i=>`<button data-card="${i.id}" ${order.includes(i.id)?'disabled':''}>${i.label}</button>`).join('')}</div><div class="panel-actions"><button class="primary" data-action="checkPuzzle" ${order.length===4?'':'disabled'}>بررسی ترتیب</button><button data-action="resetPuzzle">چیدن دوباره</button><span id="puzzleFeedback" class="hint" role="status"></span></div><p class="notice">این فعالیت، معمای داستانی است و آموزش فنی ساخت پل نیست.</p></section>`}
else if(n.type==='ending'){content=`<section class="ending"><div class="end-seal">◇</div><div class="panel-kicker">مأموریت نمونه به پایان رسید</div><h2>${n.title}</h2><p>${n.text}</p><h3>${n.outcome}</h3><div class="stats"><div><strong>${digits(engine.state.stats.care)}</strong>تصمیم همراه با دقت</div><div><strong>${digits(engine.state.journal.length)}</strong>یادداشت ثبت‌شده</div><div><strong>${digits(engine.state.visited.length)}</strong>صحنه تجربه‌شده</div></div><p class="notice">انتخاب‌های شما روند همین مأموریت خیالی را تغییر دادند؛ نتیجه تاریخی عملیات تغییر نمی‌کند.</p><button class="primary" data-action="journal">مرور دفتر مأموریت</button><button data-action="new">تجربه مسیر دیگر</button><button class="quiet" data-action="home">صفحه اصلی</button></section>`}
else{content=`<div class="stage">${(!GameArt.illustrated[n.scene]&&GameArt.portrait(n.portrait,n.pose))?`<div class="portrait ${n.side||'right'} pose-${n.pose||'neutral'}" role="img" aria-label="تصویر کمیک ${esc(n.speaker)}">${GameArt.portrait(n.portrait,n.pose)}</div>`:''}<div class="location-label">${{marsh:'ساحل هور',workshop:'کارگاه مهندسی',tent:'چادر مأموریت',bridge:'مسیر آزمایشی',dawn:'نزدیک روشنایی'}[n.scene]||''}</div></div><section class="dialogue ${n.portrait?'dialogue-with-character':''}" aria-live="polite"><div class="speaker">${esc(n.speaker)}</div><p>${esc(n.text)}</p>${n.type==='choice'?`<div class="choice-list">${engine.available().map(c=>`<button data-choice="${c.id}">${esc(c.label)}</button>`).join('')}</div>`:''}<div class="dialogue-bottom"><span class="save-status">${saveOk?'پیشرفت در این مرورگر ذخیره می‌شود':'ذخیره خودکار در دسترس نیست'} · ${digits(engine.state.visited.length)} صحنه</span>${n.type!=='choice'?'<button class="primary next" data-action="next">ادامه ←</button>':'<span class="save-status">یک پاسخ را انتخاب کن</span>'}</div></section>`}
main.innerHTML=`<section class="game">${top}${content}</section>`;window.scrollTo({top:0,behavior:'instant'});
}
function journal(){if(!engine){modal('دفتر مأموریت','<p>پس از شروع بازی، سرنخ‌ها و گزارش تصمیم‌ها اینجا ثبت می‌شوند.</p>');return}modal('دفتر مأموریت',engine.state.journal.length?engine.state.journal.map(i=>`<article class="journal-entry"><h3>${esc(i.title)}</h3><p>${esc(i.text)}</p></article>`).join(''):'<p>هنوز یادداشتی ثبت نشده. اولین مدرک را که پیدا کنی، اینجا می‌ماند.</p>')}
function map(){modal('نقشه عملیات خیبر',`<figure class="historical-map-figure"><img class="historical-map" src="${GameArt.assets.operationMap}" alt="نقشه بازسازی‌شده عملیات خیبر؛ محور هورالهویزه، جزایر مجنون، طلائیه، زید و جاده بصره به العماره" onerror="this.hidden=true;this.nextElementSibling.hidden=false"><div class="historical-map-fallback" hidden><p>تصویر نقشه به اینترنت نیاز دارد. خلاصه مسیرها در پایین آمده است.</p><a href="https://commons.wikimedia.org/wiki/File:Operation_Kheibar_map.svg" target="_blank" rel="noopener">باز کردن نقشه اصلی</a></div><figcaption>نقشه بازسازی‌شده بر پایه اطلس «نبردهای ماندگار»</figcaption></figure><div class="map-legend"><span><i class="legend-actual"></i>پیشروی ثبت‌شده</span><span><i class="legend-planned"></i>طرح ادامه عملیات</span></div><div class="map-facts-grid"><article><h3>محور اصلی هور</h3><p>حرکت آبی‌خاکی در هورالهویزه به سوی جزایر شمالی و جنوبی مجنون، با هدف تهدید جاده بصره به العماره و نزدیک‌شدن به دجله.</p></article><article><h3>محور زید و طلائیه</h3><p>محور جنوبی برای فشار زمینی و تلاش برای اتصال به نیروهای محور هور و پیشروی برنامه‌ریزی‌شده به سوی نشوه.</p></article><article><h3>آنچه محقق شد</h3><p>جزایر مجنون تصرف و نگه داشته شدند؛ الحاق برنامه‌ریزی‌شده در محور طلائیه انجام نشد.</p></article></div><p class="map-accuracy">این تصویر نقشهٔ بازسازی‌شده است، نه اسکن اصل نقشهٔ ستادی. پیکان سبز پیشروی ثبت‌شده و پیکان زرد طرح ادامه عملیات را نشان می‌دهد.</p><p class="map-credit">نقشه: AnonMoos و Gire_3pich2005، بر پایه اطلس سرهنگ مجتبی جعفری، اطلس نبردهای ماندگار، ۲۰۰۶، ص. ۹۶. <a href="https://commons.wikimedia.org/wiki/File:Operation_Kheibar_map.svg" target="_blank" rel="noopener">مجوز CC BY 3.0 و مشخصات منبع</a></p>`,true)}
function hint(){if(!engine){toast('اول مأموریت را شروع کن.');return}const n=engine.current();let t=n.type==='comic'?'با دکمه قاب بعد، صفحه را بخوان. روی گوشی، هر قاب جدا و بزرگ نشان داده می‌شود. دکمه صفحه کامل هر شش قاب را کنار هم باز می‌کند.':n.type==='inspect'?'هر کارت را باز کن؛ اگر مدرکی جا مانده باشد، دکمه برگشت خودش نامش را می‌گوید.':n.type==='puzzle'?(hintCount++?'ترتیب: بازدید اولیه، آماده‌سازی قطعه، اتصال قطعه، بازبینی نهایی.':'یادداشت یونس را بخوان. پیش از دست‌زدن به قطعه چه می‌کنی؟ پس از اتصال چه چیزی باقی می‌ماند؟'):n.type==='choice'?'می‌توانی به دفتر برگردی و نشانه‌ها را مرور کنی. انتخاب اشتباه بن‌بست ایجاد نمی‌کند، اما روی روند مأموریت اثر می‌گذارد.':n.type==='ending'?'می‌توانی دفتر را مرور کنی یا برای تجربه انتخاب‌های دیگر از نو شروع کنی.':'دکمه ادامه را بزن. دفتر و نقشه در طول گفت‌وگو در دسترس هستند.';modal('راهنمای این بخش',`<p>${t}</p>`)}
function selectChapter(id){const found=CHAPTERS.find(c=>c.id===id);if(!found)return;chapter=found;if(overlay.open)close();document.body.classList.remove('hub-screen');if(readSave())continueGame();else newGame()}
function chapters(){modal('عملیات‌ها',CHAPTERS.map(c=>`<div class="chapter-card"><span class="panel-kicker">${c.id===chapter.id&&engine?'در حال بازی':'فصل مستقل'}</span><h3>${esc(c.subtitle)} · ${esc(c.title)}</h3><p>${esc(c.description||'روایت مستقل با ذخیره و مسیر جداگانه.')}</p><button class="primary" data-chapter="${esc(c.id)}">${readSave(c.id)?'ادامه این عملیات':'ورود به این عملیات'}</button></div>`).join('')+`<p class="notice">هر عملیات در فصل و فایل پیشرفت جداگانه نگهداری می‌شود.</p>`)}
function menu(){modal('فهرست',`<div class="menu-grid">${engine?'<button data-action="resume">بازگشت به بازی</button><button data-action="journal">دفتر مأموریت</button><button data-action="history">مرور گفت‌وگوها</button><button data-action="export">دریافت فایل ذخیره</button>':''}<button data-action="import">ورود فایل ذخیره</button><button data-action="chapters">عملیات‌ها</button><button data-action="gallery">طراحی شخصیت‌ها و تصاویر</button><button data-action="about">درباره این نسخه</button><button data-action="home">صفحه اصلی</button></div>`)}
function exportSave(){if(!engine)return;const blob=new Blob([engine.export()],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='sangarsazan-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('فایل ذخیره دریافت شد.')}
function importSave(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{const file=input.files[0];if(!file)return;if(file.size>500000){toast('این فایل بیش از حد بزرگ است.');return}try{const raw=await file.text();new StoryEngine.Engine(chapter,raw);pendingImport=raw;modal('ورود ذخیره',`<p>فایل معتبر است. پیشرفت عملیات «${esc(chapter.title)}» با این فایل جایگزین شود؟</p><button class="primary" data-action="confirmImport">بارگذاری ذخیره</button><button data-action="close">بازگشت</button>`)}catch{toast('فایل ذخیره متعلق به این عملیات نیست یا معتبر نیست.')}};input.click()}
async function toggleSound(){try{if(!audio){audio=new(window.AudioContext||window.webkitAudioContext)();const buffer=audio.createBuffer(1,audio.sampleRate*4,audio.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=Math.random()*2-1;const bed=audio.createBufferSource(),ripple=audio.createBufferSource();bed.buffer=buffer;ripple.buffer=buffer;bed.loop=ripple.loop=true;ripple.playbackRate.value=.72;const low=audio.createBiquadFilter(),high=audio.createBiquadFilter();low.type='lowpass';low.frequency.value=430;high.type='highpass';high.frequency.value=950;const base=audio.createGain(),ripples=audio.createGain(),lfo=audio.createOscillator(),swell=audio.createGain();base.gain.value=.035;ripples.gain.value=.009;lfo.frequency.value=.17;swell.gain.value=.012;lfo.connect(swell).connect(base.gain);bed.connect(low).connect(base).connect(audio.destination);ripple.connect(high).connect(ripples).connect(audio.destination);bed.start();ripple.start();lfo.start();await audio.suspend()}sound=!sound;await audio[sound?'resume':'suspend']();$('#sound').textContent=sound?'آب هور روشن':'صدای آب هور';$('#sound').setAttribute('aria-pressed',String(sound))}catch{toast('صدای محیط در این مرورگر پشتیبانی نمی‌شود.')}}
const actions={operations,restart,confirmRestart:()=>{close();newGame()},core:()=>{close();home()},new:requestNew,confirmNew:()=>{close();newGame()},continue:()=>{close();continueGame()},home:()=>{close();home()},next:()=>{engine.next();save();render()},journal,map,hint,chapters,menu,close,gallery,comicPage,advanceComic:()=>{engine.advanceComic();save();render()},previousComic:()=>{engine.previousComic();save();render()},resume:close,export:exportSave,import:importSave,confirmImport:()=>{engine=new StoryEngine.Engine(chapter,pendingImport);pendingImport=null;order=[];save();close();render()},finishInspect:()=>{if(engine.finishInspection()){save();render()}else{const labels={report:'گزارش ساحل',label:'برچسب کارگاه',map:'نقشه عملیات خیبر'};const missing=engine.current().required.filter(x=>!engine.state.flags[x]);toast('برای برگشت، '+missing.map(x=>'«'+labels[x]+'»').join(' و ')+' را باز کن.')}},resetPuzzle:()=>{order=[];render()},checkPuzzle:()=>{if(engine.solve(order)){order=[];save();render()}else{$('#puzzleFeedback').textContent='این ترتیب جور درنمی‌آید. کارت‌ها را دوباره بچین؛ راهنما هم در دسترس است.'}},history:()=>modal('گفت‌وگوهای گذشته',engine.state.history.map(i=>`<div class="history-entry"><span>${esc(i.speaker)}</span><p>${esc(i.text)}</p></div>`).join('')||'<p>هنوز گفت‌وگویی ثبت نشده.</p>'),about:()=>modal('درباره این نسخه','<p>سنگرسازان / جهادگران، هسته بازی روایی دوبعدی با فصل‌های مستقل و مأموریت نمونه خیبر است. نقش بازیکن و یونس خیالی‌اند. تمام دیالوگ‌های منتسب به مهندس پورشریفی در این نمونه بازآفرینی نویسنده‌اند و نقل‌قول مستند نیستند.</p><p>محمد شخصیتی خیالی است. طراحی چهره پورشریفی بر پایه عکس یادبود آرشیوشده انجام شده و بازآفرینی هنری است. نشان جهاد سازندگی روی سینه هر دو شخصیت قرار دارد. این نسخه هنوز شامل فصل کامل ۲۰ تا ۳۰ دقیقه‌ای، دوبله و بسته اندروید نیست.</p><p>مبنای اولیه این نسخه، تحقیقات استودیو بیدرانو درباره عملیات خیبر است. نقشه نمایش‌داده‌شده بازسازی بر پایه اطلس نبردهای ماندگار است و اصل نقشه ستادی نیست.</p><p>نسخه ۰.۳ · بدون حساب کاربری · بدون ارسال ذخیره‌ها به سرور</p>')};
document.addEventListener('click',ev=>{const el=ev.target.closest('button,[data-map]');if(!el||el.disabled)return;if(el.dataset.action){actions[el.dataset.action]?.();return}if(el.dataset.chapter){selectChapter(el.dataset.chapter);return}if(el.dataset.choice){engine.choose(el.dataset.choice);save();render();return}if(el.dataset.inspect){const item=engine.inspect(el.dataset.inspect);save();render();modal(item.title,`<p>${esc(item.text)}</p>${item.id==='map'?'<figure class="evidence-map-detail"><img src="'+GameArt.assets.operationMap+'" alt="نقشه تاریخی بازسازی‌شده عملیات خیبر" onerror="this.hidden=true;this.nextElementSibling.hidden=false"><figcaption hidden>تصویر نقشه بارگذاری نشد. <a href="https://commons.wikimedia.org/wiki/File:Operation_Kheibar_map.svg" target="_blank" rel="noopener">مشاهده منبع نقشه</a></figcaption></figure><p class="notice">جزئیات طرح و نتیجه واقعی را از دکمه «نقشه» ببین.</p>':''}<button class="primary" data-action="close">ثبت شد؛ برگشت به میز</button>`);return}if(el.dataset.card){order.push(el.dataset.card);render();return}if(el.dataset.map){$('#mapInfo').textContent={workshop:'کارگاه: تطبیق برچسب‌ها و هماهنگی با گروه مهندسی.',shore:'ساحل: دریافت گزارش و هماهنگی گروه.',test:'محل آزمایش: فعالیت چهارکارتی و بازبینی نهایی.'}[el.dataset.map]}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.dataset.map){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));return}if(overlay.open||['BUTTON','INPUT','A'].includes(e.target.tagName))return;if((e.key===' '||e.key==='Enter')&&screen==='game'){if(engine.current().type==='dialogue'){e.preventDefault();actions.next()}else if(engine.current().type==='comic'){e.preventDefault();actions.advanceComic()}}});
$('#closeModal').onclick=close;$('#menuButton').onclick=menu;$('#coreButton').onclick=()=>{close();home()};$('#restartButton').onclick=restart;$('#brand').onclick=e=>{e.preventDefault();if(screen==='game')menu();else home()};$('#sound').onclick=toggleSound;overlay.addEventListener('click',e=>{if(e.target===overlay){const r=overlay.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}});document.addEventListener('visibilitychange',()=>{if(document.hidden&&audio)audio.suspend();else if(audio&&sound)audio.resume()});
for(const c of CHAPTERS)StoryEngine.validate(c);home();
})();
